                chain_index=len(systems),
                atom_spec=atoms,
                study_id=study.study_id,
            )
        )
    return systems


def load_validation_study_systems(study_id: str) -> list[SystemRecord]:
    if study_id not in VALIDATION_STUDIES:
        raise KeyError(f"Unknown validation study: {study_id}")

    study = VALIDATION_STUDIES[study_id]
    systems = _load_chain_study(study) if study.parser == "chain" else _load_named_block_study(study)
    if not systems:
        raise ValueError(f"No systems parsed from {study.source_file}")
    return systems


def load_family_systems(family: str) -> list[SystemRecord]:
    if family not in CHAIN_STUDY_FILES:
        raise KeyError(f"Unknown family: {family}")
    study_id = {
        "acene": "fragment_alpha",
        "ppv": "fragment_beta",
        "nitro": "fragment_gamma",
    }[family]
    return load_validation_study_systems(study_id)


